def SolveSchroedinger(y0, En, l, R):
    from scipy import integrate
    import numpy as np

    def integrand(r, y):
        return Schroed_deriv(y, r, l, En)

    y_integrated = integrate.solve_ivp(integrand, [R[-1], R[0]], y0, t_eval=R[::-1], method='RK45').y[:, ::-1]

    def simpson(f, a, b, n):
        h = (b - a) / n
        integral = f(a) + f(b)
        for i in range(1, n):
            x = a + i * h
            if i % 2 == 0:
                integral += 2 * f(x)
            else:
                integral += 4 * f(x)
        integral *= h / 3
        return integral

    norm_factor = simpson(lambda r: y_integrated[0]**2, R[0], R[-1], len(R))
    ur = y_integrated[0] / np.sqrt(norm_factor)

    return ur
