def init_system(N, rho):
    import numpy as np

    V = N / rho  # Volume of the cubic box
    L = V**(1/3)  # Length of the side of the cubic box

    # Determine the number of particles along each dimension
    n_particles_per_dim = int(round(N**(1/3)))

    # Create a grid of positions
    positions = np.zeros((N, 3))
    counter = 0
    for i in range(n_particles_per_dim):
        for j in range(n_particles_per_dim):
            for k in range(n_particles_per_dim):
                if counter < N:
                    positions[counter] = np.array([i, j, k]) * L / (n_particles_per_dim - 1)
                    counter += 1
                else:
                    break

    return positions, L
