def apply_channel(K, rho, sys=None, dim=None):
    if dim is None:
        dim = [rho.shape[0]]
    if sys is None:
        sys = list(range(len(dim)))

    identity_matrices = [np.eye(d, dtype=float) for d in dim]

    result = np.zeros_like(rho, dtype=float)
    for kraus in K:
        current_tensor = 1
        for i, d in enumerate(dim):
            if i in sys:
                current_tensor = tensor(current_tensor, kraus)
            else:
                current_tensor = tensor(current_tensor, identity_matrices[i])
        result += np.dot(current_tensor, np.dot(rho, current_tensor.conj().T))

    return result
